void mainImage( out vec4 fragColour, in vec2 fragCoord )
{
    vec3 ray;
    ray.xy = .7*(fragCoord-iResolution.xy*.5)/iResolution.y;
    ray.z = sqrt(1.-dot(ray.xy,ray.xy)); // fisheye

    // fake a reflective sphere in the middle of the view
    float r = .2;
    float l = length(ray.xy);
    if ( l < r )
    {
        vec3 n;
        n.xy = .85*ray.xy/r; n.z = -sign(ray.z)*sqrt(1.-dot(n.xy,n.xy));
        ray = reflect(ray,n);
    }

    vec2 a = vec2(sin(iTime*.2)*.4,iTime*.1);
    ray.yz = ray.yz*cos(a.x)+sin(a.x)*vec2(-1,1)*ray.zy;
    ray.zx = ray.zx*cos(a.y)+sin(a.y)*vec2(-1,1)*ray.xz;

    fragColour = texture(iChannel0,ray);
}
